import{_ as l,I as d,c as p,o as a,a3 as n,b as r,w as t,a as i,J as s,a4 as c,bV as m,bW as u,bX as g,bY as h}from"./chunks/framework.Cc9k46oU.js";const _=JSON.parse('{"title":"SyncOps: Korean SI/Solution Operations & Dual-Rate P&L, Surety Bond, and Research Note Control Platform","description":"An enterprise PMO agent platform that unifies core management metrics for contract-based SI and software solution firms—including real-time dual-rate project P&L, KOSA technical grade staffing matrices, four major surety bond insurances, Subcontracting Act payment deadline monitoring, and SHA-256 electronic research notes for R&D tax credits.","frontmatter":{"title":"SyncOps: Korean SI/Solution Operations & Dual-Rate P&L, Surety Bond, and Research Note Control Platform","sidebarTitle":"Overview","description":"An enterprise PMO agent platform that unifies core management metrics for contract-based SI and software solution firms—including real-time dual-rate project P&L, KOSA technical grade staffing matrices, four major surety bond insurances, Subcontracting Act payment deadline monitoring, and SHA-256 electronic research notes for R&D tax credits.","head":[["meta",{"name":"keywords","content":"SyncOps, SI PMO, PSA, Dual-Rate P&L, KOSA Technical Grade, Surety Bond Insurance, Subcontracting Act 15-day 60-day, Late Interest, Electronic Research Notes, SHA-256 Timestamp Authentication, AgentScope Java"}],["meta",{"property":"og:title","content":"SyncOps: Korean SI/Solution Operations & Dual-Rate P&L, Surety Bond, and Research Note Control Platform"}],["meta",{"property":"og:description","content":"An enterprise PMO agent that centrally monitors client billing rate vs. actual cost dual P&L, KOSA grade M/M matrices, four major surety bonds, and Subcontracting Act compliance"}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/logo.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/syncops/"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/en/syncops/"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/syncops/"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/syncops/"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/syncops/"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/syncops/"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"SyncOps: Korean SI/Solution Operations & Dual-Rate P&L, Surety Bond, and Research Note Control Platform | Empasy Docs"}],["meta",{"property":"og:description","content":"An enterprise PMO agent platform that unifies core management metrics for contract-based SI and software solution firms—including real-time dual-rate project P&L, KOSA technical grade staffing matrices, four major surety bond insurances, Subcontracting Act payment deadline monitoring, and SHA-256 electronic research notes for R&D tax credits."}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/syncops/"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"SyncOps: Korean SI/Solution Operations & Dual-Rate P&L, Surety Bond, and Research Note Control Platform | Empasy Docs"}],["meta",{"name":"twitter:description","content":"An enterprise PMO agent platform that unifies core management metrics for contract-based SI and software solution firms—including real-time dual-rate project P&L, KOSA technical grade staffing matrices, four major surety bond insurances, Subcontracting Act payment deadline monitoring, and SHA-256 electronic research notes for R&D tax credits."}]],"sort":1},"headers":[],"relativePath":"en/syncops/index.md","filePath":"en/syncops/index.md","lastUpdated":1795293539000}'),f={name:"en/syncops/index.md"};function y(S,e,b,A,v,x){const o=d("Mermaid");return a(),p("div",null,[e[2]||(e[2]=n('<h1 id="syncops-korean-si-solution-operations-p-l-compliance-control-platform" tabindex="-1">SyncOps: Korean SI/Solution Operations &amp; P&amp;L/Compliance Control Platform <a class="header-anchor" href="#syncops-korean-si-solution-operations-p-l-compliance-control-platform" aria-label="Permalink to “SyncOps: Korean SI/Solution Operations &amp; P&amp;L/Compliance Control Platform”">​</a></h1><blockquote><p><strong>For Non-Developers &amp; Adoption Evaluation</strong>: For a straightforward product overview, visit the <a href="https://ops.empasy.io/en/" target="_blank" rel="noopener">SyncOps Product Homepage (ops.empasy.io)</a>. To explore the UI without installation, try the <a href="https://sync.empasy.io/en/products/sync-ops#demo" target="_blank" rel="noopener">Unified Demo Portal</a>, or download brochures and proposal PDFs from the <a href="/en/proposals/">Proposal Library</a>.</p></blockquote><blockquote><p><strong>Tier 3 Enterprise SI PMO &amp; Profit/Compliance Agent Platform</strong><br> Service Domain: <code>https://ops.empasy.io</code> · Standard API Prefix: <code>/api/v1/ops</code></p></blockquote><p><strong>SyncOps</strong> is an enterprise business operations (PSA/PMO) agent that autonomously manages the core performance and compliance indicators of contract-based SI (System Integration) and software solution companies on a single platform—including <strong>dual P&amp;L tracking (client contract billing rate vs. actual input cost)</strong>, <strong>KOSA software engineer grade and monthly M/M utilization matrices</strong>, <strong>expiration tracking for the four major surety bond insurances (bid, performance, advance payment, and defect warranty)</strong>, <strong>Subcontracting Act 15-day/60-day payment deadline monitoring</strong>, and <strong>SHA-256 timestamp-authenticated electronic research notes for R&amp;D tax credits under the Restriction of Special Taxation Act</strong>.</p><hr><h2 id="_1-key-drivers-and-challenges-addressed" tabindex="-1">1. Key Drivers and Challenges Addressed <a class="header-anchor" href="#_1-key-drivers-and-challenges-addressed" aria-label="Permalink to “1. Key Drivers and Challenges Addressed”">​</a></h2><p>With legacy manual spreadsheets or general manufacturing-oriented ERPs, it is difficult to track in real time the <strong>dual-rate gap (client billing rate vs. actual costs across full-time staff, freelancers, and subcontracts)</strong>, <strong>complex consortium share settlements</strong>, and <strong>statutory deadlines under the Subcontracting Act</strong> unique to contract-based IT service firms.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Comparison Item</th><th style="text-align:left;">Legacy Excel &amp; Fragmented ERP Operations</th><th style="text-align:left;">SyncOps Korean SI Operations Platform</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Project P&amp;L Calculation</strong></td><td style="text-align:left;">Client contract rates and actual assigned labor costs are managed separately, so deficits are discovered only after project completion</td><td style="text-align:left;"><strong>Contract rate vs. actual cost dual-rate engine</strong> automatically calculates real-time contribution margin and operating margin upon weekly timesheet approval</td></tr><tr><td style="text-align:left;"><strong>Staffing &amp; Utilization</strong></td><td style="text-align:left;">Manual spreadsheet tracking causes over-allocation (<code>&gt;1.0 M/M</code>) and delays visibility into idle (bench) personnel</td><td style="text-align:left;"><strong>Automated KOSA grade calculation and monthly M/M utilization heatmap matrix</strong> paired with <code>pgvector</code>-based AI recommendations for optimal replacement staff</td></tr><tr><td style="text-align:left;"><strong>Surety Bonds &amp; Subcontracting Act</strong></td><td style="text-align:left;">Manual tracking of bid, performance, advance, and defect surety bond renewals and 15-day/60-day subcontract payment deadlines risks legal penalties</td><td style="text-align:left;"><strong>D-Day expiration alerts for four major surety bonds</strong> and <strong>automated subcontract statutory deadline and late interest (15.5% p.a.) calculator</strong> proactively eliminate legal risks</td></tr><tr><td style="text-align:left;"><strong>R&amp;D Research Note Evidence</strong></td><td style="text-align:left;">Handwritten research notes for national R&amp;D projects and corporate R&amp;D center tax credits leave audit trails vulnerable</td><td style="text-align:left;"><strong>SHA-256 hash timestamp-authenticated electronic research notes</strong> with automated Git commit hash mapping satisfy Article 10 R&amp;D tax credit requirements</td></tr><tr><td style="text-align:left;"><strong>Staff Offboarding &amp; Handover</strong></td><td style="text-align:left;">When a PM or sales representative leaves, key-man client contacts and verbal negotiation histories are lost</td><td style="text-align:left;"><strong>One-click handover center</strong> and AI handover summary briefings (<code>HandoverBriefing</code>) reliably preserve client operational continuity</td></tr></tbody></table><hr><h2 id="_2-six-core-value-chain-domains" tabindex="-1">2. Six Core Value-Chain Domains <a class="header-anchor" href="#_2-six-core-value-chain-domains" aria-label="Permalink to “2. Six Core Value-Chain Domains”">​</a></h2>',10)),(a(),r(c,null,{default:t(()=>[s(o,{id:"mermaid-99",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20SyncOps%20%5B%22SyncOps%20Enterprise%20PMO%206%20Core%20Value%20Chains%22%5D%0A%20%20%20%20%20%20%20%20D1%5B%221.%20Executive%20%26%20P%26L%20Control%3Cbr%2F%3E(%2Fexecutive%2F*)%22%5D%0A%20%20%20%20%20%20%20%20D2%5B%222.%20Business%20%26%20Contract%20Management%3Cbr%2F%3E(%2Fcontract%2F*)%22%5D%0A%20%20%20%20%20%20%20%20D3%5B%223.%20Project%20Execution%3Cbr%2F%3E(%2Fproject%2F*)%22%5D%0A%20%20%20%20%20%20%20%20D4%5B%224.%20Talent%20%26%20Resource%20Management%3Cbr%2F%3E(%2Ftalent%2F*)%22%5D%0A%20%20%20%20%20%20%20%20D5%5B%225.%20Milestone%20%26%20Financial%20Settlement%3Cbr%2F%3E(%2Fsettlement%2F*)%22%5D%0A%20%20%20%20%20%20%20%20D6%5B%226.%20Solution%20%26%20R%26D%20Assetization%3Cbr%2F%3E(%2Fproduct%2F*)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20D2%20--%3E%20D3%0A%20%20%20%20D4%20--%3E%20D3%0A%20%20%20%20D3%20--%3E%20D5%0A%20%20%20%20D3%20--%3E%20D6%0A%20%20%20%20D3%20%26%20D5%20--%3E%20D1%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=n('<h3 id="_2-1-executive-p-l-control-executive-dashboard-executive-profit-matrix-executive-ai-control" tabindex="-1">2.1 Executive &amp; P&amp;L Control (<code>/executive/dashboard</code>, <code>/executive/profit-matrix</code>, <code>/executive/ai-control</code>) <a class="header-anchor" href="#_2-1-executive-p-l-control-executive-dashboard-executive-profit-matrix-executive-ai-control" aria-label="Permalink to “2.1 Executive &amp; P&amp;L Control (/executive/dashboard, /executive/profit-matrix, /executive/ai-control)”">​</a></h3><ul><li><strong>Real-Time Dual-Rate P&amp;L Control</strong>: Separates client-billed contract unit prices (<code>billing_unit_price</code>) from actual input unit costs (<code>cost_unit_price</code> covering payroll, social insurance, severance reserves, and outsourcing fees) to simulate real-time cost of goods sold (COGS) and operating margins per project.</li><li><strong>5-Dimensional P&amp;L Pivot Matrix</strong>: Drills down into P&amp;L by client, project, delivery department, employment type (full-time/freelancer/subcontract), and period.</li><li><strong>AI Staffing &amp; Risk Control</strong>: Detects budget burndown overruns and projects at risk of turning unprofitable early, providing actionable remediation guidance.</li></ul><h3 id="_2-2-business-contract-management-contract-list-contract-clients-contract-vendors-contract-compliance-alerts" tabindex="-1">2.2 Business &amp; Contract Management (<code>/contract/list</code>, <code>/contract/clients</code>, <code>/contract/vendors</code>, <code>/contract/compliance-alerts</code>) <a class="header-anchor" href="#_2-2-business-contract-management-contract-list-contract-clients-contract-vendors-contract-compliance-alerts" aria-label="Permalink to “2.2 Business &amp; Contract Management (/contract/list, /contract/clients, /contract/vendors, /contract/compliance-alerts)”">​</a></h3><ul><li><strong>Unified Prime/Subcontract Management &amp; Sequential Addendums</strong>: Systematically tracks solo awards and consortium share ratios (joint execution and split execution), along with change-request (CR)-linked contract addendum histories.</li><li><strong>Unified Tracking for Four Major Surety Bonds</strong>: Monitors expiration dates and direct insurance premium costs for bid (<code>BID</code>), performance (<code>PERFORMANCE</code>), advance payment (<code>ADVANCE</code>), and defect warranty (<code>DEFECT</code>) surety policies issued by Seoul Guarantee Insurance (SGI) and the Korea Software Financial Cooperative.</li><li><strong>Client &amp; Vendor Key-Man CRM and One-Click Handover</strong>: Manages client and vendor contact records, consultation histories, and official correspondence PDFs with corporate seals, transferring ownership in bulk to successors in a single transaction during personnel changes.</li></ul><h3 id="_2-3-project-execution-p-l-simulation-project-list-project-profit-simulator-project-timesheet-approval" tabindex="-1">2.3 Project Execution &amp; P&amp;L Simulation (<code>/project/list</code>, <code>/project/profit-simulator</code>, <code>/project/timesheet-approval</code>) <a class="header-anchor" href="#_2-3-project-execution-p-l-simulation-project-list-project-profit-simulator-project-timesheet-approval" aria-label="Permalink to “2.3 Project Execution &amp; P&amp;L Simulation (/project/list, /project/profit-simulator, /project/timesheet-approval)”">​</a></h3><ul><li><strong>Weekly Timesheet &amp; Effort Approval</strong>: Separates and aggregates weekly actual effort (M/M) into client SI cost (<code>CLIENT_SI</code>) and core R&amp;D assetization (<code>CORE_RD</code>).</li><li><strong>Change Request (CR) Governance</strong>: Quantifies additional effort and incremental billing amounts for new client requirements and links them directly to contract amendments.</li></ul><h3 id="_2-4-talent-resource-management-talent-employee-talent-kosa-grade-talent-assignment-gantt-talent-bench-monitor" tabindex="-1">2.4 Talent &amp; Resource Management (<code>/talent/employee</code>, <code>/talent/kosa-grade</code>, <code>/talent/assignment-gantt</code>, <code>/talent/bench-monitor</code>) <a class="header-anchor" href="#_2-4-talent-resource-management-talent-employee-talent-kosa-grade-talent-assignment-gantt-talent-bench-monitor" aria-label="Permalink to “2.4 Talent &amp; Resource Management (/talent/employee, /talent/kosa-grade, /talent/assignment-gantt, /talent/bench-monitor)”">​</a></h3><ul><li><strong>KOSA Software Engineer Grade Assessment</strong>: Automatically determines Special (<code>SPECIAL</code>), Advanced (<code>ADVANCED</code>), Intermediate (<code>INTERMEDIATE</code>), and Beginner (<code>BEGINNER</code>) grades based on academic credentials, national technical certifications, and KOSA-recognized career days.</li><li><strong>Monthly M/M Utilization Gantt Chart &amp; Bench Monitoring</strong>: Visualizes per-person project allocation rates to prevent over-allocation exceeding 100% (<code>1.0 M/M</code>) while tracking idle (bench) staff and upcoming roll-offs in real time.</li><li><strong>Staff Replacement Approval Governance</strong>: Automatically verifies whether replacement candidates meet equivalent or higher KOSA grades and manages formal client approval letters.</li></ul><h3 id="_2-5-milestone-financial-settlement-settlement-milestone-settlement-ar-aging" tabindex="-1">2.5 Milestone &amp; Financial Settlement (<code>/settlement/milestone</code>, <code>/settlement/ar-aging</code>) <a class="header-anchor" href="#_2-5-milestone-financial-settlement-settlement-milestone-settlement-ar-aging" aria-label="Permalink to “2.5 Milestone &amp; Financial Settlement (/settlement/milestone, /settlement/ar-aging)”">​</a></h3><ul><li><strong>Automated Subcontracting Act Article 6 &amp; 13 Deadline Monitoring</strong>: Automatically computes statutory payment deadlines (<strong>within 15 days</strong> of receiving prime contract milestone payment and <strong>within 60 days</strong> of deliverable inspection), triggers violation and approaching-deadline (D-7) alerts, and calculates statutory late interest (15.5% per annum) when overdue.</li><li><strong>Electronic Tax Invoices &amp; AR Aging Settlement</strong>: Tracks proportional advance payment deductions, 3.3% freelancer withholding tax deductions, and accounts receivable aging days.</li></ul><h3 id="_2-6-solution-r-d-assetization-product-releases-product-rnd-notes" tabindex="-1">2.6 Solution &amp; R&amp;D Assetization (<code>/product/releases</code>, <code>/product/rnd-notes</code>) <a class="header-anchor" href="#_2-6-solution-r-d-assetization-product-releases-product-rnd-notes" aria-label="Permalink to “2.6 Solution &amp; R&amp;D Assetization (/product/releases, /product/rnd-notes)”">​</a></h3><ul><li><strong>Electronic Research Notes for Article 10 R&amp;D Tax Credits</strong>: Preserves tamper-evident electronic research notes by combining KOITA-registered dedicated researchers&#39; R&amp;D activity logs, Git commit hashes, author and reviewer electronic signatures, and <strong>SHA-256 timestamp authority (TSA) hashes</strong>.</li><li><strong>SI Custom Feature Core Backport Hub</strong>: Manages the review pipeline for assetizing high-value features built during SI projects back into core proprietary solutions (<code>SyncBoot</code>, <code>SyncCMS</code>, etc.), along with per-client deployed configurations (Installed Base).</li></ul><hr><h2 id="_3-three-stage-standard-business-operations-process" tabindex="-1">3. Three-Stage Standard Business Operations Process <a class="header-anchor" href="#_3-three-stage-standard-business-operations-process" aria-label="Permalink to “3. Three-Stage Standard Business Operations Process”">​</a></h2>',14)),(a(),r(c,null,{default:t(()=>[s(o,{id:"mermaid-209",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20actor%20PMO%20as%20PMO%20%2F%20Project%20Manager%0A%20%20%20%20participant%20Ops%20as%20SyncOps%20Core%20Server%0A%20%20%20%20participant%20Swarm%20as%20SyncOps%20AI%20Agent%20Swarm%0A%20%20%20%20participant%20Verse%20as%20SyncVerse%20Central%20Control%20Tower%0A%0A%20%20%20%20PMO-%3E%3EOps%3A%20Stage%201%3A%20Register%20Awarded%20Project%20%26%20Link%20Surety%20Bonds%20%2F%20Prime-Subcontracts%0A%20%20%20%20PMO-%3E%3EOps%3A%20Stage%202%3A%20Allocate%20M%2FM%20by%20KOSA%20Grade%20%26%20Run%20Dual-Rate%20P%26L%20Simulation%0A%20%20%20%20Ops-%3E%3ESwarm%3A%20Invoke%20Real-Time%20TalentMatcher%20%26%20RiskGuard%20Verification%0A%20%20%20%20Swarm--%3E%3EPMO%3A%20Recommend%20Optimal%20Bench%20Staff%20%26%20Confirm%20Target%20Margin%20(30%25)%0A%20%20%20%20PMO-%3E%3EOps%3A%20Stage%203%3A%20Reconcile%20Milestone%20Inspection%20%2F%20Subcontract%20Settlement%20%26%20SHA-256%20R%26D%20Note%20Timestamping%0A%20%20%20%20Swarm--%3E%3EVerse%3A%20Report%20Subcontract%2015%2F60-Day%20Compliance%20%26%20Research%20Note%20Hash%20Integrity%20Briefing%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=n('<hr><h2 id="live-screens-core-workflows" tabindex="-1">Live Screens &amp; Core Workflows <a class="header-anchor" href="#live-screens-core-workflows" aria-label="Permalink to “Live Screens &amp; Core Workflows”">​</a></h2><h3 id="_1-executive-summary-dashboard-contract-project-p-l-control" tabindex="-1">1. Executive Summary Dashboard &amp; Contract Project P&amp;L Control <a class="header-anchor" href="#_1-executive-summary-dashboard-contract-project-p-l-control" aria-label="Permalink to “1. Executive Summary Dashboard &amp; Contract Project P&amp;L Control”">​</a></h3><p>Monitor enterprise-wide total contract value, real-time operating margins by project, staffing utilization (M/M), and legal compliance alerts from a single executive dashboard.</p><p><img src="'+m+'" alt="SyncOps Executive Summary P&amp;L Dashboard" loading="lazy"></p><h3 id="_2-client-contract-rate-vs-actual-input-cost-dual-rate-p-l-matrix" tabindex="-1">2. Client Contract Rate vs. Actual Input Cost Dual-Rate P&amp;L Matrix <a class="header-anchor" href="#_2-client-contract-rate-vs-actual-input-cost-dual-rate-p-l-matrix" aria-label="Permalink to “2. Client Contract Rate vs. Actual Input Cost Dual-Rate P&amp;L Matrix”">​</a></h3><p>Separately aggregate client billing rates and actual costs across full-time staff, freelancers, and subcontractors to analyze real-time contribution margins by client, project, department, and period.</p><p><img src="'+u+'" alt="SyncOps Dual-Rate P&amp;L Pivot Matrix" loading="lazy"></p><h3 id="_3-four-major-surety-bond-expiration-tracking-subcontracting-act-payment-monitoring" tabindex="-1">3. Four Major Surety Bond Expiration Tracking &amp; Subcontracting Act Payment Monitoring <a class="header-anchor" href="#_3-four-major-surety-bond-expiration-tracking-subcontracting-act-payment-monitoring" aria-label="Permalink to “3. Four Major Surety Bond Expiration Tracking &amp; Subcontracting Act Payment Monitoring”">​</a></h3><p>Proactively eliminate legal risks by automatically computing renewal D-Days for bid, performance, advance payment, and defect surety policies alongside statutory subcontract payment deadlines (15 days after receipt, 60 days after inspection) and late interest.</p><p><img src="'+g+'" alt="SyncOps Surety Bond and Subcontracting Act Compliance Monitoring" loading="lazy"></p><h3 id="_4-kosa-grade-staffing-matrix-utilization-gantt-chart-electronic-research-notes" tabindex="-1">4. KOSA Grade Staffing Matrix, Utilization Gantt Chart &amp; Electronic Research Notes <a class="header-anchor" href="#_4-kosa-grade-staffing-matrix-utilization-gantt-chart-electronic-research-notes" aria-label="Permalink to “4. KOSA Grade Staffing Matrix, Utilization Gantt Chart &amp; Electronic Research Notes”">​</a></h3><p>Visualize project assignment schedules (Gantt chart) and over-allocations by KOSA software engineer grade, and manage timestamp-authenticated electronic research notes.</p><p><img src="'+h+'" alt="SyncOps Staffing Allocation Gantt Chart and Utilization Control" loading="lazy"></p><hr><h2 id="_4-official-technical-documentation-index" tabindex="-1">4. Official Technical Documentation Index <a class="header-anchor" href="#_4-official-technical-documentation-index" aria-label="Permalink to “4. Official Technical Documentation Index”">​</a></h2><ul><li><strong><a href="./architecture">System Architecture &amp; DB Schema</a></strong>: Detailed specifications of the four AgentScope Java internal agent swarms, dual-rate P&amp;L engine, and PostgreSQL 18.6 domain schema (<code>ops_*</code>)</li><li><strong><a href="./mcp-tools">MCP Tools &amp; REST API Reference</a></strong>: Tool specifications for <code>ops_analyze_project_profitability</code>, <code>ops_check_allocation_overload</code>, <code>ops_audit_subcontract_payment</code>, and <code>ops_verify_rnd_note_hash</code>, plus the <code>/api/v1/ops/...</code> API guide</li></ul>',17))])}const D=l(f,[["render",y]]);export{_ as __pageData,D as default};
